    val ListChecks: ImageVector by lazy { phosphor("ListChecks", LIST_CHECKS) }
    val MagnifyingGlass: ImageVector by lazy { phosphor("MagnifyingGlass", MAGNIFYING_GLASS) }
    val Plus: ImageVector by lazy { phosphor("Plus", PLUS) }
    val SlidersHorizontal: ImageVector by lazy {
        phosphor(
            "SlidersHorizontal",
            SLIDERS_HORIZONTAL,
        )
    }
    val Timer: ImageVector by lazy { phosphor("Timer", TIMER) }
    val Trash: ImageVector by lazy { phosphor("Trash", TRASH) }
    val UsersThree: ImageVector by lazy { phosphor("UsersThree", USERS_THREE) }

    val all: List<ImageVector>
        get() =
            listOf(
                ArrowLeft,
                ArrowRight,
                Barbell,
                Camera,
                CaretRight,
                ChartLineUp,
                ChatTeardropText,
                Check,
                Copy,
                Gear,
                Image,
                Info,
                ListChecks,
                MagnifyingGlass,
                Plus,
                SlidersHorizontal,
                Timer,
                Trash,
                UsersThree,
            )
}

// Icon tints replace the fill, so the colour here only has to be opaque.
private fun phosphor(
    name: String,
    vararg paths: String,
): ImageVector =
    ImageVector
        .Builder(name, 24.dp, 24.dp, 256f, 256f)
        .apply { paths.forEach { addPath(addPathNodes(it), fill = SolidColor(Color.Black)) } }
        .build()

